import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("Account with id '$id' already exists")
        }
        val normalized = normalizeAmount(initial)
        if (normalized.signum() < 0) {
            throw IllegalArgumentException("Initial balance must be non-negative")
        }
        balances[id] = normalized
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        val b = balances[id] ?: throw NoSuchElementException("No account with id '$id'")
        return b
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        val a = normalizeAmount(amount)
        if (a.signum() <= 0) {
            throw IllegalArgumentException("Transfer amount must be positive")
        }
        val fromBalance = balances[from] ?: throw NoSuchElementException("No account with id '$from'")
        val toBalance = balances[to] ?: throw NoSuchElementException("No account with id '$to'")
        if (fromBalance < a) {
            throw IllegalStateException("insufficient funds")
        }
        balances[from] = fromBalance.subtract(a)
        log.getValue(from).add(a.negate())
        balances[to] = toBalance.add(a)
        log.getValue(to).add(a)
    }

    fun history(id: String): List<BigDecimal> {
        val l = log[id] ?: throw NoSuchElementException("No account with id '$id'")
        return l.toList()
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            if (n <= 0) {
                throw IllegalArgumentException("n must be positive")
            }
            val normalizedTotal = normalizeAmount(total)
            if (normalizedTotal.signum() < 0) {
                throw IllegalArgumentException("Total must be non-negative")
            }
            // Convert total to cents
            val totalCents = normalizedTotal.movePointRight(2).toLong()
            val baseCents = totalCents / n
            val remainder = totalCents % n
            val result = ArrayList<BigDecimal>(n)
            // Larger parts first: remainder parts get baseCents + 1, rest get baseCents
            for (i in 0 until n) {
                val cents = if (i < remainder) baseCents + 1 else baseCents
                result.add(BigDecimal(cents).movePointLeft(2))
            }
            return result
        }

        private fun normalizeAmount(amount: BigDecimal): BigDecimal {
            // Check if amount has more than 2 decimal places
            val stripped = amount.stripTrailingZeros()
            val scale = stripped.scale()
            if (scale > 2) {
                throw IllegalArgumentException("Amount must have at most 2 decimal places")
            }
            return amount.setScale(2, RoundingMode.UNNECESSARY)
        }
    }
}
