class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "capacity must be >= 1" }
    }

    private val map = LinkedHashMap<K, V>()

    operator fun get(key: K): V? {
        val value = map[key] ?: return null
        // Mark as most recently used by removing and re-adding
        map.remove(key)
        map[key] = value
        return value
    }

    operator fun set(key: K, value: V) {
        if (map.containsKey(key)) {
            // Update existing key: remove and re-add to mark as most recently used
            map.remove(key)
            map[key] = value
        } else {
            // Insert new key
            map[key] = value
            if (map.size > capacity) {
                // Evict the least recently used entry (first entry in LinkedHashMap)
                val firstKey = map.keys.first()
                val firstValue = map[firstKey]!!
                map.remove(firstKey)
                onEvict(firstKey, firstValue)
            }
        }
    }

    fun remove(key: K): V? {
        return map.remove(key)
    }

    val size: Int
        get() = map.size

    fun keys(): List<K> {
        return map.keys.toList()
    }

    operator fun contains(key: K): Boolean {
        return map.containsKey(key)
    }
}
