        null -> "null"
        is Boolean -> value.toString()
        is String -> escapeString(value)
        is Int -> value.toString()
        is Long -> value.toString()
        is Float -> value.toString()
        is Double -> {
            if (value.isNaN() || value.isInfinite()) {
                throw IllegalArgumentException("Non-finite double value: $value")
            }
            value.toString()
        }
        is Enum<*> -> "\"${value.name}\""
        is Map<*, *> -> {
            if (value.isEmpty()) return "{}"
            val sb = StringBuilder()
            sb.append("{")
            if (indent > 0) sb.append("\n")
            val entries = value.entries.toList()
            for ((i, entry) in entries.withIndex()) {
                val key = entry.key
                if (key !is String) {
                    throw IllegalArgumentException("Map key must be a String, got: ${key?.let { it::class.simpleName } ?: "null"}")
                }
                if (indent > 0) sb.append(" ".repeat(indent))
                sb.append(escapeString(key))
                sb.append(":")
                if (indent > 0) sb.append(" ")
                sb.append(toJson(entry.value, indent))
                if (i < entries.size - 1) sb.append(",")
                if (indent > 0) sb.append("\n")
            }
            if (indent > 0) sb.append(" ".repeat(indent - indent))
            sb.append("}")
            return sb.toString()
        }
        is List<*> -> {
            if (value.isEmpty()) return "[]"
            val sb = StringBuilder()
            sb.append("[")
            if (indent > 0) sb.append("\n")
            for ((i, item) in value.withIndex()) {
                if (indent > 0) sb.append(" ".repeat(indent))
                sb.append(toJson(item, indent))
                if (i < value.size - 1) sb.append(",")
                if (indent > 0) sb.append("\n")
            }
            if (indent > 0) sb.append(" ".repeat(indent - indent))
            sb.append("]")
            return sb.toString()
        }
        is Array<*> -> {
            if (value.isEmpty()) return "[]"
            val sb = StringBuilder()
            sb.append("[")
            if (indent > 0) sb.append("\n")
            for ((i, item) in value.withIndex()) {
                if (indent > 0) sb.append(" ".repeat(indent))
                sb.append(toJson(item, indent))
                if (i < value.size - 1) sb.append(",")
                if (indent > 0) sb.append("\n")
            }
            if (indent > 0) sb.append(" ".repeat(indent - indent))
            sb.append("]")
            return sb.toString()
        }
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.simpleName}")
    }
}

private fun escapeString(s: String): String {
    val sb = StringBuilder()
    sb.append("\"")
    for (c in s) {
        when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\f' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (c < 0x20) {
                    sb.append("\\u")
                    sb.append(String.format("%04x", c.code))
                } else {
                    sb.append(c)
                }
            }
        }
    }
    sb.append("\"")
    return sb.toString()
}
