sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)
fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val n = input.length

    while (i < n) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        // Parentheses
        if (c == '(') {
            tokens.add(Token.Paren(true, i))
            i++
            continue
        }
        if (c == ')') {
            tokens.add(Token.Paren(false, i))
            i++
            continue
        }

        // Strings
        if (c == '"' || c == '\'') {
            val quote = c
            val startPos = i
            i++
            val sb = StringBuilder()
            var terminated = false
            while (i < n) {
                val ch = input[i]
                if (ch == '\\') {
                    if (i + 1 >= n) {
                        throw TokenizeException("Unterminated string", startPos)
                    }
                    val next = input[i + 1]
                    when (next) {
                        'n' -> sb.append('\n')
                        else -> sb.append(next)
                    }
                    i += 2
                } else if (ch == quote) {
                    terminated = true
                    i++
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }
            if (!terminated) {
                throw TokenizeException("Unterminated string", startPos)
            }
            tokens.add(Token.Str(sb.toString(), startPos))
            continue
        }

        // Identifiers
        if (c.isLetter() || c == '_') {
            val startPos = i
            i++
            while (i < n) {
                val ch = input[i]
                if (ch.isLetterOrDigit() || ch == '_' || ch == '.') {
                    i++
                } else {
                    break
                }
            }
            tokens.add(Token.Ident(input.substring(startPos, i), startPos))
            continue
        }

        // Numbers
        if (c.isDigit() || (c == '-' && canHaveNegativeNumber(tokens))) {
            val startPos = i
            var j = i
            if (j < n && input[j] == '-') {
                j++
            }
            // Must have at least one digit after optional minus
            if (j >= n || !input[j].isDigit()) {
                throw TokenizeException("Invalid number", startPos)
            }
            // Parse integer part
            while (j < n && input[j].isDigit()) {
                j++
            }
            // Check for fraction
            var hasFraction = false
            if (j < n && input[j] == '.') {
                hasFraction = true
                j++
                // Must have at least one digit after the dot
                if (j >= n || !input[j].isDigit()) {
                    throw TokenizeException("Invalid number", startPos)
                }
                while (j < n && input[j].isDigit()) {
                    j++
                }
            }
            // Check if next char is part of an identifier (e.g., 5abc) - this would be an error
            // Actually, per spec, numbers are just digits with optional fraction. If followed by identifier chars, that's an error.
            // But wait, the spec says identifiers can have dots. So 5.5 is a number. What about 5.a? That would be invalid.
            // Let's check: after parsing the number, if the next char is a letter or underscore, it's an error.
            if (j < n && (input[j].isLetter() || input[j] == '_')) {
                throw TokenizeException("Invalid number", startPos)
            }
            val numStr = input.substring(startPos, j)
            val value = numStr.toDouble()
            tokens.add(Token.Num(value, startPos))
            i = j
            continue
        }

        // Operators (longest match first)
        if (c == '=' || c == '!' || c == '<' || c == '>' || c == '&' || c == '|') {
            val startPos = i
            // Try two-character operators first
            if (i + 1 < n) {
                val two = input.substring(i, i + 2)
                if (two == "==" || two == "!=" || two == "<=" || two == ">=" || two == "&&" || two == "||") {
                    tokens.add(Token.Op(two, startPos))
                    i += 2
                    continue
                }
            }
            // Single character operators
            if (c == '<' || c == '>' || c == '!') {
                tokens.add(Token.Op(c.toString(), startPos))
                i++
                continue
            }
            // '=' and '&' and '|' alone are not valid operators
            throw TokenizeException("Unexpected character '$c'", i)
        }

        // Minus that is not part of a number
        if (c == '-') {
            throw TokenizeException("Unexpected character '-'", i)
        }

        // Anything else is an error
        throw TokenizeException("Unexpected character '$c'", i)
    }

    return tokens
}

private fun canHaveNegativeNumber(tokens: List<Token>): Boolean {
    if (tokens.isEmpty()) return true
    val last = tokens.last()
    return last is Token.Op || (last is Token.Paren && last.open)
}
